from pathlib import Path
import json, html, math
R=Path(__file__).resolve().parent
D=json.loads((R/'analysis.json').read_text(encoding='utf-8'))
C=D['catalog']; e=html.escape
def n(x): return f'{x:,}' if isinstance(x,int) else str(x)
def stamp(t): return f'{int(t)//60:02d}:{t%60:04.1f}'
def frame(t):
    paths=[('missing',t),('menus',t),('upgrades',t),('combo',t),('normal12',t),('boss10',t),('boss20',t),('firstfight',t),('overview',t)]
    for group,v in paths:
        p=Path(group)/f'{v:09.3f}.jpg'
        if (R/p).exists():return p.as_posix()
    p=Path('overview')/f'{round(t/6)*6:09.3f}.jpg'
    return p.as_posix() if (R/p).exists() else 'overview-sheet-01.jpg'
def time(t):return f'<a href="{frame(t)}" target="_blank">{stamp(t)}</a>'
def table(headers,rows,cls=''):
    return '<div class="table-wrap"><table class="'+cls+'"><thead><tr>'+''.join('<th>'+str(x)+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def fig(src,caption):return f'<figure><a href="{src}" target="_blank"><img src="{src}" loading="lazy" alt="{e(caption)}"></a><figcaption>{caption}</figcaption></figure>'
def video(src,caption):return f'<figure><video controls preload="none" playsinline src="{src}"></video><figcaption>{caption}</figcaption></figure>'
def sec(id,title,body):return f'<section id="{id}"><h2>{title}</h2>{body}</section>'
parts=[]
parts.append('''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>용사는 타이밍 플레이 분석 · Last Bell 적용 기획 v8</title><link rel="stylesheet" href="report.css"></head><body><header><span>LAST BELL / REFERENCE STUDY 08 / 2026.10.23</span><h1>손맛은 읽기 쉽게.<br>성장은 선택이 보이게.</h1><p class="lead">사용자 제공 12분 26.6초 플레이 영상과 현재 Unity 코드를 대조했습니다. 화면 흐름·성장·유물·전투 규칙을 나누어 분석하고, Last Bell에서 유지할 것과 바꿀 것을 정리했습니다.</p><a class="pill" href="preview-v8.html">직접 조작하는 미리보기 →</a><a class="pill" href="combat-preview.mp4">8초 전투 연출 영상</a><a class="pill" href="preview-overview.png">6개 화면 한눈에 보기</a><p class="muted">기획 전용 · Unity / GameData / 빌드 미변경 · 영상 속 게임 ver.1.0.7 · 기존 성장 계정의 녹화</p></header><main><nav><a href="#decision">적용 방향</a><a href="#flow">화면 흐름</a><a href="#growth">별·강화</a><a href="#relic">유물</a><a href="#combat">전투·연속 공격</a><a href="#monsters">몬스터 수치</a><a href="#balance">우리 밸런스</a><a href="#ui">화면 명세</a><a href="#delivery">구현 순서</a><a href="#evidence">근거·검수</a></nav>''')
parts.append(sec('decision','01. 이번에 바꿀 핵심', '''<div class="grid"><article><div class="metric">01 <small>성장 가독성</small></div><h3>별 / 강화 레벨 / 실제 증가량을 분리</h3><p>별은 성장 적성입니다. 구매 직전 <b>50 → 130</b>처럼 실제 정수 변화를 보여줍니다. 10→11, 20→21의 돌파와 이후 계속 오르는 비용은 유지합니다.</p></article><article><div class="metric">02 <small>유물 선택</small></div><h3>작은 선택 창, 구체적인 효과</h3><p>현재 중앙 3후보 구조를 유지합니다. 선택 후 신규 또는 Lv.2→3, 효과 4→6%p를 보여주고 아래 버튼으로 확정합니다. 전역 보유와 캐릭터별 장착을 구분합니다.</p></article><article><div class="metric">03 <small>전투 박자</small></div><h3>타격 시각 유지, 파동 진행만 통일</h3><p>0·240·480 예고 / 720ms 첫 단타, 480ms 연타 간격을 유지합니다. 제안은 파동을 매번 480ms로 통일하고 현재 타격의 종만 강조하는 것입니다.</p></article></div><p class="callout">현재 구현된 두루마리 프롤로그, 작은 유물 선택, 안쪽으로 옮긴 모바일 버튼, 화면 정중앙 완벽 회피 파동, 아래 방향키 쳐내기, 11스테이지 체크포인트를 보존합니다. 캐릭터·몬스터 아트와 승인된 공격 모션도 유지합니다.</p>'''+fig('preview-overview.png','변경안 6화면. 기존 Last Bell 아트를 재사용한 기획 시안이며 Unity 실행 화면은 아닙니다.')))
