parts.append(sec('relic','04. 유물 종류와 선택 경험', '''<p><span class="tag">영상 관찰</span> 목록의 12종과 보상 후보의 신규 2종을 합쳐 <b>14종</b>을 식별했습니다. 개별 효과의 정확한 %·고정 수치·MAX 레벨은 표시되지 않아 복원할 수 없습니다. 아래는 녹화에서 확인한 범위이며 게임 전체 유물 목록이 아닙니다.</p>'''+table(['유물','역할','효과 요지','관찰 레벨','원본'],relrows)+'''<p>“모든 영웅에게 적용”은 반복해서 확인됩니다. 다만 목록 하단 12/12와 다음 슬롯 200다이아는 보이지만, 전체 소지·장착 상한의 상세 규칙은 영상만으로 확정하지 않습니다. 원작의 전역 누적 효과와 우리 3슬롯 장착 체계는 성장 폭이 크게 다릅니다.</p><h3>현재 Last Bell의 10종</h3>'''+table(['유물','효과','Lv.1 / 2 / 3 / 4 / 5 값 (%)','데이터 ID'],ourrelic)+'''<h3>적용안: 선택 창의 구조를 유지하고, 효과의 차이를 읽게 한다</h3><p>유물 후보는 <b>아이콘 + 이름</b>만 표시합니다. 하나를 누르면 아래 공유 설명 영역에서 신규/중복, 현재 레벨→다음 레벨, 현재 효과→다음 효과를 보여줍니다. 선택 버튼을 누르기 전에는 획득하지 않습니다. 확정 후 중복 클릭은 차단하고 보상이 한 번만 지급되어야 합니다.</p><p>현재 전역 보유 / 캐릭터별 최대 3슬롯 장착을 유지합니다. 원작처럼 모든 유물을 자동 적용하면 기존 슬롯 선택의 의미와 난도가 달라집니다. 도감은 이름, 효과, 보유 Lv., 선택 캐릭터의 장착 여부, 슬롯 제한을 구분해 표시합니다.</p>'''+table(['문제','제안','세이브 처리'],[
['울림 고리·여명의 종인: 1 / 1.5 / 2 / 2.5 / 3%는 정수 표시·반올림 시 중간 레벨 효과가 겹침','두 유물 모두 1 / 2 / 3 / 4 / 5%로 정수 단계화. 공격 판정에 쓰는 최종 값과 표시 값은 같은 계산 결과 사용.','같은 ID·보유 Lv. 유지. 레벨별 효과 테이블만 다음 적용 단계에서 수정.'],
['새벽의 조각: 7.5 / 10.5% 표시','6 / 8 / 10 / 12 / 14%로 정수 증가. 청동 매듭과 역할 중복은 남으므로 둘의 획득 비중을 별도 점검.','기존 유물을 삭제하거나 다른 능력으로 교체하지 않음.'],
['저레벨 공격 % 유물은 최종 공격 반올림으로 1레벨 차이가 사라질 수 있음','설명에 보너스 %와 실제 총 공격력 둘 다 표시. 최종 공격 최소 +1을 무조건 보장하는 규칙은 여러 유물 중첩 상향을 일으켜 도입하지 않음.','합산한 효과를 최종 단계에서 한 번만 정수화.'],
['MAX 중복 또는 모든 후보 MAX','현재 전장 보상표의 골드 전환을 미리 표시. 예: 11~20 구간 2,399 G.','지급·선택 확정은 1회 트랜잭션. 재진입 시 재지급 방지.']])+'''<h3>역할 확장이 필요할 때만 추가할 신규 후보</h3><p>기존 10종을 변형·폐기하지 않고 새 ID로 추가하는 후속안입니다. 이번 미리보기와 현행 밸런스에는 포함하지 않았습니다.</p>'''+table(['가칭','Lv.1→5','조건 / 제한'],[['되울림의 파편','완벽 회피 후 첫 공격 피해 +10 / 15 / 20 / 25 / 30%','500ms 반격 기회 안에서 첫 1회 소비. 연속 공격 회피를 강요하는 시점에는 공격 취소 보장.'],['따뜻한 심지','전투 종료 시 최대 HP의 3 / 4 / 5 / 6 / 7% 회복','전투 중 흡혈과 분리. 치유는 정수, 최대 HP 초과 없음.'],['수호자의 균열','보스 피해 +5 / 7 / 9 / 11 / 13%','일반 적 효과 없음. 기존 공격%와 곱연산 폭증 대신 같은 피해 보너스 묶음에서 합산 검토.']])+fig('previews/relics-960.png','선택한 유물의 레벨과 실제 효과 변화를 공통 하단 영역에서 확인하는 시안.')))
timingrows=[]
for k,count in [('단타',1),('2연타',2),('3연타',3)]:
    timingrows.append([k,' → '.join('/'.join(str(i*720+j*240) for j in range(3)) for i in range(count)),' / '.join(str(count*720+i*480) for i in range(count)),' / '.join(str(count*720+i*480-480) for i in range(count))])
parts.append(sec('combat','05. 공격 주기, 연속 공격, 타격감', '''<h3>원작에서 확인한 전투 문법</h3>'''+table(['항목','영상 표본','해석'],[
['플레이어 공격',f'{time(295.9)} 부근 이후 약 0.8~0.9초 간격으로 반복','사용자 입력 간격이 포함된 관찰치. 엔진의 최소 쿨다운으로 단정할 수 없음.'],
['일반 적 준비→타격',f'{time(294.1)}→294.9초, 299.7→300.6~300.7초','약 0.8~1.0초. 일반 적 한 종류의 2표본.'],
['일반 적 타격→다음 타격','294.9→300.6~300.7초','약 5.7~5.8초. 모든 적의 공격 주기가 아님.'],
['10층 보스 타격 간격',f'{time(234.6)}→238.3초','약 3.7초. 이후 기절/반격으로 다음 주기가 달라짐.'],
['20층 2연속 공격',f'{time(608.0)}·608.8초 예고 → 609.6·610.3초 접촉','두 방향을 미리 알려준 뒤 순서대로 공격. 타격 간 약 700~800ms.'],
['반격 기회',f'{time(606)} 부근 약 1.5초 이상','Chance! / 방사형 표시 / 반격 문구. 기회 발생 유물도 있으므로 완벽 회피 단독 규칙으로 단정 불가.']])+'''<p class="muted">프레임 표본 간격 100~200ms, 추정 시각 오차 약 ±100~200ms. 원본은 가변 프레임레이트입니다. 화면 녹화만으로 입력 시각·기기 지연·판정창 폭을 측정할 수 없으므로 원작의 완벽 회피 허용 ms는 미확인입니다.</p><p>원작은 ↑·←·↓ 3회피와 우측 공격, 하단 중앙 스킬 2개를 씁니다. Last Bell은 현재의 <b>네 방향과 아래 버튼 쳐내기</b>를 유지합니다. 원작의 ! 세 개가 한 묶음으로 보인다고 3연타라는 뜻은 아닙니다. 우리 종 하나=공격 1회 규칙이 더 직접적입니다.</p>'''+video('clips/reference-combo.mp4','원본 10:05.5–10:13.5. 소리 포함 발췌. 예고 묶음과 실제 타격 순서를 구분해서 볼 수 있습니다.')+'''<h3>720ms 약속은 그대로, 파동 시계만 정리</h3>'''+table(['패턴','순차 깜빡임 시작(ms)','실제 타격(ms)','변경안 파동 시작(ms)'],timingrows)+'''<p>예고가 시작되면 종 1~3개를 고정 위치에 둡니다. 각 방향 히트박스가 3번씩 깜빡인 뒤 모든 타격을 순서대로 진행합니다. 이미 끝난 종은 그 자리에 흐리게 남기고, 다음 타격 종만 밝은 테두리로 강조합니다. 색 외에도 번호·테두리·진행 상태가 달라 소리를 꺼도 순서를 알 수 있습니다.</p><p><b>현재 코드의 주의점:</b> 모든 타격 파동의 길이가 600ms인데, 두 번째 타격은 480ms 뒤입니다. 화면은 아직 처리하지 않은 첫 위협의 파동만 그리므로 첫 타격 직후 다음 파동이 이미 <b>20%</b> 진행된 시각부터 보입니다. 원점이 화면 밖 12.5% 지점이라 20%는 화면 가장자리 도달 시점입니다. 중앙으로 갑자기 순간 이동하는 현상이라는 뜻은 아닙니다.</p><p><b>비교할 변경안:</b> 모든 파동의 길이를 480ms로 통일합니다. 단타는 240ms(두 번째 깜빡임)에서 출발해 720ms에 중앙 접촉, 2연타는 960→1,440, 1,440→1,920ms입니다. 후속 파동은 직전 타격 순간에 원점에서 새로 시작합니다. 경고/판정 시간은 바꾸지 않고 파동의 속도·출발 관계만 일정하게 만듭니다.</p><p class="callout note">첫 파동의 화면 내 노출은 현재 약 480ms에서 제안 약 384ms로 짧아집니다. 장점은 동일 속도와 박자 정렬이고, 단점은 첫 파동을 읽는 시간이 줄어드는 것입니다. 따라서 미리보기에서 현재 600ms와 제안 480ms를 비교하고, 초심자 회피 성공률이 떨어지면 첫 파동 600ms를 유지하는 혼합안을 선택합니다. “더 쉽다”는 결론은 아직 플레이테스트로 검증하지 않았습니다.</p><p>방향 기억 부담은 마지막 예고 이후 <b>현재 타격 히트박스만 6% 채움·점선</b>으로 약하게 남겨 줄입니다. 텍스트로 “오른쪽으로 피하기”를 붙이지 않습니다. 강한 섬광·공격 이펙트가 파동 접촉과 종을 가리지 않게 파동/종을 이펙트 위, 실제 입력 UI 아래 레이어에 둡니다.</p><h3>현재 판정과 반격: 바꾸지 않을 값</h3>'''+table(['구분','현행 값','화면에 전달할 의미'],[
['일반 회피','활성 160ms + 복귀 100ms','올바른 방향을 미리 입력하면 범위 내에서 회피.'],['완벽 회피','타격 전 마지막 60ms','화면 정중앙에서 원형 파동이 화면 밖까지 확산. 바닥 링으로 대체하지 않음.'],['반격','완벽 회피 후 500ms','공격 입력 시 회피 동작을 끝내고 기준 위치 복귀 후 전진 공격. 완벽 회피 자체의 별도 피해 배율은 없음.'],['공격','접촉 200ms / 간격 500ms','예고와 반격 타이밍을 읽는 기준. 위협 중 공격 입력 취소/회피 우선권 유지.'],['기절','일반 1,500 / 중간보스 1,200 / 보스 1,000ms','완벽 회피의 기절 누적량 증가로 공격 기회가 생김.'],['기절 누적','일반 회피 20 / 완벽 회피 40, 보스 ×0.4','반격은 단순 데미지 보너스보다 회피 성공→기절→공격 기회로 연결.']])+'''<h3>타격감: 움직임의 크기보다 접촉 순간을 선명하게</h3>'''+table(['관찰한 원작 요소','Last Bell 적용 제안','수치 / 보호 조건'],[
['긴 접근 공격과 빠른 원위치 복귀','승인된 전진 공격·후방 회피 모션을 유지하고 접촉 프레임에만 검 궤적과 작은 파편 추가','실제 공격 사거리·피격 판정은 변경하지 않음. 적까지 이동한 것처럼 보이는 연출만 사용.'],
['밝은 피격 반전·굵은 피해 숫자','현재 맞을 때 45ms 백색→75ms 복원 유지. 피해 숫자에 진한 외곽선, 치명타는 크기 약 1.2배','초당 반복 플래시·전체 화면 백색 점멸 추가 안 함. 본체·숫자·종의 우선순위 분리.'],
['짧은 접촉 정지감','선택안: 접촉 포즈 30ms, 치명타 45ms, 처치 60ms를 시각만 유지','다음 위협까지 160ms 이하이면 생략. Core 시계·입력·파동·종·UI는 정지하지 않음.'],
['반격 때 큰 성공 인지','정중앙 확산 340ms와 공격 버튼의 밝은 테두리 500ms','강한 파동은 완벽 회피만. 일반 회피는 작고 짧은 잔상. 이펙트 감소 설정에서도 얇은 외곽선 유지.'],
['치명타 흔들림·충돌 소리','현재 승인된 7.2 SFX와 치명타/처치 흔들림을 유지. 일반 피격은 약 2px 몸체 밀림만 검토','HUD와 터치 버튼은 흔들지 않음. 영상에서 정확한 히트스톱·음량을 계측한 것으로 표현하지 않음.']])+video('combat-preview.mp4','Last Bell 변경안 8초 무음 동작 시안. 2연타 후 3연타, 중앙 확산·제자리 복귀 후 전진 공격을 보여줍니다. 실제 Unity 애니메이터 재생/전투 검증 영상은 아닙니다.')))
