for r in D['referenceStages']:
    monrows.append([r['stage'],e(r['name']),r['hp'] or '미확인',r['damage'] or '미확인',n(r['rewardObserved']) if r['rewardObserved'] is not None else '미확인',time(r['t'])])
parts.append(sec('monsters','06. 몬스터 체력·피해·보상: 확인 가능한 범위', '''<p>영상은 다수 유물이 이미 성장한 계정입니다. 공격력 18 표기에도 타격 피해 13~24, 추가 피해 3·4·5, 더 큰 지속 피해와 치명타 숫자가 섞입니다. 관통·흡혈·감소·추가 피해가 있어 숫자 하나를 몬스터 기본 공격력이나 플레이어 기본 공격력으로 옮기면 안 됩니다.</p>'''+table(['층','적 이름','체력','공격 피해','관찰 획득 현상금*','표본'],monrows)+'''<p class="muted">* 현상금은 처치 표시 또는 지갑 차이로 기록한 이번 플레이 결과입니다. 탐욕 유물 등의 영향을 받으므로 기본 보상 테이블이 아닙니다. 적 명칭은 화면 표기를 전사했습니다. 21층 이후는 녹화되지 않았습니다.</p><h3>체력 추정 방법과 한계</h3><p>첫 적은 8 피해 후 HP 막대가 감소하고, 22 추가 피해 뒤 다시 감소하며 마지막 23 타격에서 쓰러집니다. 원본을 1,200px로 줄인 캡처에서 전체 막대 약 137px, 8 피해 후 약 23px·누적 30 피해 후 약 82px가 줄어드는 표본을 이용하면 <b>약 50 HP, 넓게 45~55</b>가 맞는 범위입니다. 정확한 데이터 값이라는 뜻은 아닙니다.</p><p>12층은 17 피해 전후 막대가 약 8px 줄어드는 표본에서 <code>17 × 137 / 8 ≈ 291</code>, 경계 1px만 달라도 약 259~333입니다. 추가 오차를 포함해 <b>250~340</b> 범위로만 기록합니다. 보스는 작은 피해가 한 픽셀보다 작고 다른 효과가 중첩되어 유효한 최대 HP 역산을 포기합니다.</p><p><b>적 전체의 층별 HP·공격력 배율 공식은 이 영상에서 확인되지 않습니다.</b> 더 정확히 알려면 유물·스킬을 해제한 영웅, 동일 공격력, 전후 HP 숫자 또는 픽셀 원본, 반복 표본이 필요합니다. 원작 추정치를 억지로 우리 데이터의 근거로 사용하지 않습니다.</p>'''+fig('hp-crops.jpg','첫 적의 HP 막대와 피해 숫자 표본. 압축·테두리·잔상 때문에 범위 추정으로만 사용합니다.')+'''<h3>이번 플레이에서 나타난 전투 길이</h3>'''+table(['대상','대략적 구간','길이','기획적 의미'],[['5층 골렘','03:04–03:07','약 3초','보유 유물과 반격 등으로 매우 빨리 끝난 표본. 모든 5층의 기준 아님.'],['10층 거인','03:52–04:29','약 37초','패턴을 여러 번 읽고 반격하는 보스전.'],['15층 설인','05:47–06:05','약 18초','일반 적보다 늘어나는 중간 관문.'],['20층 미노타우루스','07:56–10:24','약 148초','이번 계정/입력의 결과. 높은 체력만으로 후반을 만들면 장기 반복 전투가 된다는 참고.']])+'''<p>관찰한 구간은 전투 시작·종료 화면 전환을 포함한 근사치입니다. 기절·스킬·사용자 입력·유물 영향이 있으므로 원작의 설계 목표 시간으로 해석하지 않습니다.</p>'''))
costs=C['economy']['upgradeCosts']; pricebands=[]
for z in range(5):
    lo=z*10+1;hi=lo+9
    pricebands.append([f'{lo}–{hi}', ['기본 10 G','직전 ×3','직전 ×3.5','직전 ×4','직전 ×4.5'][z],['+25%','+30%','+35%','+40%','+45%'][z],n(costs[lo])+' → '+n(costs[hi]),n(sum(costs[lo:hi+1]))])
currentstages=[]
for s in C['stages'][:20]:
    g=C['economy']['normalGoldPerStage'][s['number']];g*=3 if s['kind']=='miniboss' else 5 if s['kind']=='boss' else 1
    currentstages.append([s['number'],e(s['enemyId']),n(s['maxHp']),n(s['damage']),n(g),' / '.join(map(str,s['sequenceWeights']))])
futureRows=[]
for s in [20,21,25,30,31,35,40,41,45,50]:
    r=D['futureBalance'][s-1];futureRows.append([s,n(r['attack3']),n(r['hp3']),n(r['oldHp']),n(r['enemyHp']),n(r['enemyDamage']),str(r['normalHits'])+'회',str(r['hitsToDie'])+'회'])
parts.append(sec('balance','07. Last Bell의 비용과 후반 난도', '''<h3>가격은 현재의 영구적인 구간 상승을 유지</h3><p>돌파 비용만 튀었다가 낮아지는 원작 규칙 대신, 사용자 요청에 맞는 현재 가격을 유지합니다. 아래 “레벨”은 강화 목표 레벨입니다. 매 단계 올림해 정수 골드로 지급·차감합니다.</p>'''+table(['목표 레벨','구간 진입','구간 내 매 강화','첫 비용 → 끝 비용','해당 10레벨 총비용/스텟'],pricebands)+'''<p>예: 9→10 = 75 G, 10→11 = 225 G, 11→12 = 293 G, 19→20 = 2,399 G, 20→21 = 8,397 G. 각 스텟 Lv.50 누적은 4,178,943,264 G, 네 스텟이면 16,715,773,056 G입니다. 저장·계산은 현재처럼 64비트 정수를 사용하고 UI는 큰 수를 줄여 표시하되 구매 창에서 전체 비용을 확인할 수 있게 합니다.</p><h3>현재 1~20스테이지: 값을 알고 조정한다</h3>'''+table(['스테이지','적 ID','최대 HP','공격 피해','기본 처치 골드','단타 / 2연타 / 3연타 가중치'],currentstages)+'''<p>현재 11스테이지는 10스테이지 보스보다도 HP가 높고 피해가 44→180으로 크게 뜁니다. 3성 강화 Lv.10의 HP 340은 180 두 번에, Lv.11의 HP 655는 네 번에 쓰러집니다. 돌파 HP가 없으면 생존이 크게 어려워지는 구조는 이미 존재합니다. 이번 기획은 1~20 데이터를 추가로 무작정 올리지 않습니다.</p><p>기본 보상 기준 첫 구간 합계 1,374 G, 네 스텟 모두 Lv.10 비용 1,348 G입니다. 두 번째 구간 보상은 16,422 G인데 스텟 하나 Lv.10→20에 9,633 G가 듭니다. 따라서 모든 능력치가 스테이지와 같은 레벨이라는 가정은 실제 한 번의 클리어 예산과 맞지 않습니다. 공격 우선·생존 우선·공명 우선 빌드별로 검증해야 합니다.</p><h3>21~50 확장 시: 체력 배율을 타격 횟수로 제한</h3><p>이전 v7 장기안의 전장마다 HP ×10을 그대로 연장하면 50스테이지 보스 HP 8,651,641, 3성 공격 Lv.50 = 6,967 기준 평타 약 1,242회입니다. 회피를 어렵게 하는 것과 처치를 지나치게 오래 걸리게 하는 것은 다릅니다. 아래는 <b>확장용 제안</b>이며 현재 20스테이지 프로토타입에 추가하지 않습니다.</p>'''+table(['스테이지','비교 공격','비교 HP','기존 장기안 적 HP','제안 적 HP','제안 적 피해','평타 처치 횟수','피격 사망 횟수'],futureRows)+'''<p>비교 기준은 3성, 공격·체력 각각 Lv.=스테이지, 유물/치명타/기절/회복 없는 순수 계산입니다. 20은 현재값, 21부터 제안값입니다. 실제 플레이에서 이 레벨을 동시에 살 수 있다는 뜻이 아닙니다. 후반 일반 적은 24→32→40회 수준, 보스는 60→72→84회의 기본 타격 예산으로 제한하고, 한 전장을 넘어설 때 HP/피해가 눈에 띄게 오르게 합니다.</p><p>생존은 해당 비교 HP의 약 51~75%를 한 번에 잃게 해서 후반 2피격 사망 압박을 유지합니다. 보스 체력은 기절·반격을 활용하면 약 30~45초에 끝나는 것을 플레이테스트 목표로 삼습니다. 이것은 검증된 결과가 아닌 목표이며 실제 투자 예산과 기절 점유율을 넣어 다시 조정해야 합니다.</p><details><summary>확장 제안 산식·검증 시나리오</summary><pre>z = floor((stage−1)/10), k = (stage−1)%10
21~49 일반 적 평타 목표 = 24 + 8(z−2) + 0.75k
중간보스(k=4)는 +10회
30/40/50 보스 목표 = 60/72/84회
제안 HP = 반올림(3성 해당 Lv. 공격 × 목표 횟수)
제안 피해 = 올림(3성 해당 Lv. HP × [0.51 + 0.01k + 중간보스0.10 또는 보스0.15])</pre><p>공격 우선: 재화 60% 공격 / 30% 체력 / 10% 공명. 생존 우선: 35% / 55% / 10%. 균형: 40% / 40% / 20%. 각 구매는 실제 비용과 잔액으로만 처리하고, 새 계정·11 체크포인트 계정·유물 MAX 계정으로 별도 측정합니다. 이 배분은 테스트 시나리오이며 구현된 자동 강화가 아닙니다.</p><p>측정 항목: 일반 적/보스 실제 처치 시간, 1·2·3연타별 완벽/일반/실패 비율, 사망까지 피격 횟수, 재도전당 획득 골드와 가능한 강화 횟수. 다음 실험은 새 계정 5회·숙련 계정 5회씩, 공격 대기 시간을 포함해 비교합니다.</p></details>'''))
parts.append(sec('ui','08. 화면 배치·상태·문구 명세', '''<p>기준은 가로 960×540, 작은 모바일 640×360, 넓은 모바일 1200×540입니다. 작은 화면은 통째로 축소하지 않고 캐릭터 초상을 좌측 목록 아래로 옮깁니다. 실제 앱에서는 Safe Area 내부에 같은 구조를 배치합니다. 아래 좌표는 노치가 없는 미리보기 기준입니다.</p>'''+table(['영역','960×540 bounds (x,y,w,h)','640×360 bounds','앵커 / 우선순위'],[
['플레이어 상태','(22,16,200,66)','(22,12,142,53)','Safe Area 좌상단. 현재 HP/스테이지 우선.'],['적 상태','(320,18,320,63)','(230,12,180,52)','Safe Area 상단 중앙. 종과 수직 분리.'],['공격 종','중심 (480,121), 간격 48','중심 (320,93), 간격 40','화면 중앙 기준. 1~3칸 고정, 다음 타격 테두리.'],['좌측 방향패드','좌 (56,350,64,64), 상 (128,278,64,64), 하 (128,422,64,64), 우 (200,350,64,64)','좌 (44,212,56,56), 상 (108,148,56,56), 하 (108,276,56,56), 우 (172,212,56,56)','Safe Area 좌하단. 4개 입력 유지, 가장자리 여백 44 이상.'],['공격','(768,360,112,112)','(504,236,88,88)','Safe Area 우하단. 오른쪽 여백 48 이상.'],['유물 선택 창','(200,98,560,344)','(80,39,480,282)','화면 중앙. 바깥은 약하게 어둡게, 전투 배경 유지.'],['로비 강화','(410,78,526,306)','(194,62,422,215)','우측 패널. 작은 화면도 각 행에 비용 표시. 긴 수는 축약.'],['확정·재도전 버튼','최소 높이 48','최소 높이 48','48 논리 픽셀은 시작점. 실제 dp/기기 검증 별도.']])+'''<p>원작은 넓은 빈 중앙과 하단 고정 체력 막대로 전투를 읽게 합니다. 우리는 중앙 파동이 핵심이므로 중앙에 체력 텍스트를 쌓지 않고 HP를 상단에 고정합니다. 몬스터 수치 텍스트는 설정에서 막대만 표시 가능하게 하고, 피해 숫자는 종/중앙 접촉점과 겹치지 않는 캐릭터 주변으로 띄웁니다.</p><div class="grid">'''+fig('previews/wire-lobby.png','캐릭터·성장 영역의 와이어프레임.')+fig('previews/wire-battle.png','전투 / 상태 / 종 / 엄지 입력 영역의 와이어프레임.')+'''</div><h3>상태별 행동</h3>'''+table(['화면 / 상태','플레이어가 보는 것','동작 / 복구'],[
['프롤로그 / 최초·다시보기','짧은 4문단, 진행 표시, 건너뛰기','일시정지, 다음 문단, 마지막 문단 종료 후 로비. 스토리 자동 스크롤을 판정 시간에 연결하지 않음.'],['캐릭터 / 잠금','담·린 제작 중, 흐린 버튼','현재 선택할 수 없음. 실제 언락 조건이 생길 때 조건 표기로 대체.'],['강화 / 정상','현재→다음 수치, 현재 Lv., 골드 비용','1회 클릭=1회 구매. 잔액/레벨 변경은 같은 처리에서 완료.'],['강화 / 골드 부족','필요 골드의 부족분','가격을 숨기거나 유료 구매 화면을 자동 열지 않음. 닫거나 출전 가능.'],['강화 / MAX','MAX, 더하기 비활성','다음 레벨 견적을 만들지 않음.'],['유물 / 미선택','후보 3개, 설명 대기','확정 비활성. 이미지/이름 터치 후 설명 표시.'],['유물 / 선택·확정','선택 테두리, 현재→다음 효과','확정 후 재확정 차단. 닫힘/복귀 때 선택만으로 지급하지 않음.'],['전투 / 일시정지·배경 전환','같은 전투 화면, 정지 상태','Core 시계와 표현 시계를 함께 정지, 복귀 시 경과 시간 폭주 없음.'],['전투 / 이펙트 감소·무음','얇은 파동, 종의 순번·테두리, 실제 히트박스','색·소리·진동만으로 방향과 박자를 전달하지 않음.'],['결과 / 사망','사망 스테이지, 재화, 다음 출전 지점','다시하기는 저장 체크포인트. 10 돌파 후 11부터. 로비는 정산 후 이동.']])+'''<h3>실제 UI에 남길 최소 문구</h3>'''+table(['ID','문구 / 변수','공간·조건'],[['growth.next','{현재} → {다음}','강화 행 1줄. 정수·단위 포함. 긴 수는 축약, 상세에서 원값.'],['growth.missing','골드 {부족분} 부족','패널 하단 1줄, 최대 30자. 버튼 연타로 중복 토스트 쌓지 않음.'],['relic.duplicate','Lv.{현재} → Lv.{다음} · {효과} {이전} → {이후}%p','선택 설명 1~2줄. 아이콘 카드 안에는 넣지 않음.'],['relic.shared','보유는 공용 · 장착한 종지기에게 적용','하단 보조문구 1줄. 전역 자동 적용과 구분.'],['result.stage','{스테이지}스테이지에서 쓰러졌습니다','결과 상단 1줄.'],['result.retry','다음 도전은 {체크포인트}스테이지부터','다시하기 버튼 위 1줄.']])+fig('previews/lobby-640.png','640×360 강화 시안. 초상·목록·강화 영역을 재배치한 작은 화면 기준.')))
